    "dynasty": "Tang dynasty",
    "approximateDate": "618–907",
    "originalChinese": [
      [
        "昔日戲言身後事",
        "今朝都到眼前來",
        "衣裳已施行看盡",
        "針線猶存未忍開"
      ],
      [
        "尚想舊情憐婢僕",
        "也曾因夢送錢財",
        "誠知此恨人人有",
        "貧賤夫妻百事哀"
      ]
    ],
    "translation": [
      [
        "We joked, long ago, about one of us dying, But suddenly, before my eyes, you are gone.",
        "Almost all your clothes have been given away;",
        "Your needlework is sealed, I dare not look at it....",
        "I continue your bounty to our men and our maids --Sometimes, in a dream, I bring you gifts...."
      ],
      [
        "This is a sorrow that all mankind must know --But not as those know it who have been poor together."
      ]
    ],
