    "originalChinese": [
      [
        "重帷深下莫愁堂",
        "臥後清宵細細長",
        "神女生涯原是夢",
        "小姑居處本無郎"
      ],
      [
        "風波不信菱枝弱",
        "月露誰教桂葉香",
        "直道相思了無益",
        "未妨惆悵是清狂"
      ]
    ],
    "translation": [
      [
        "There are many curtains in your care-free house, Where rapture lasts the whole night long....",
        "What are the lives of angels but dreams If they take no lovers into their rooms?...",
        "Storms are ravishing the nut-horns,",
        "Moon-dew sweetening cinnamon-leaves I know well enough naught can come of this union,"
      ],
      [
        "Yet how it serves to ease my heart!"
      ]
    ],
